//
// Catalog model mirroring crates/nexttouch-catalog (schema
// "nexttouch-catalog/1"). The JSON is generated by tools/gen_catalog.py
// from ipsw.me and bundled identically on all platforms.
//
// Honesty rule: status is only tested/tested_slow/experimental for the
// legacy range the baseline engine implements. Every iOS 8/9/10 entry is
// NOT_BOOTING_YET in v0.1.0 — the picker must never claim one boots.

package com.c12n.nexttouch.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

@Serializable
enum class FirmwareStatus {
    @SerialName("tested") TESTED,
    @SerialName("tested_slow") TESTED_SLOW,
    @SerialName("experimental") EXPERIMENTAL,
    @SerialName("not_booting_yet") NOT_BOOTING_YET;

    val label: String
        get() = when (this) {
            TESTED -> "Tested"
            TESTED_SLOW -> "Tested, slow"
            EXPERIMENTAL -> "Experimental"
            NOT_BOOTING_YET -> "Not booting yet"
        }

    val isRunnable: Boolean get() = this != NOT_BOOTING_YET
}

@Serializable
enum class DeviceTier {
    @SerialName("legacy") LEGACY,
    @SerialName("target") TARGET,
    @SerialName("experimental") EXPERIMENTAL,
    @SerialName("future") FUTURE;

    val label: String
        get() = when (this) {
            LEGACY -> "Legacy (engine-supported)"
            TARGET -> "Target (A5 — in development)"
            EXPERIMENTAL -> "Experimental (A6 — planned)"
            FUTURE -> "Future (arm64 — planned)"
        }
}

/** Internal engineering stage ladder (planned -> skeleton -> kernel ->
 * userland -> springboard -> usable -> qualified). iOS 8/9/10 entries
 * are all PLANNED in v0.1.0; see docs/ROADMAP.md for the M1-M6 test
 * definitions a stage claim must be backed by. */
@Serializable
enum class Stage {
    @SerialName("planned") PLANNED,
    @SerialName("skeleton") SKELETON,
    @SerialName("kernel") KERNEL,
    @SerialName("userland") USERLAND,
    @SerialName("springboard") SPRINGBOARD,
    @SerialName("usable") USABLE,
    @SerialName("qualified") QUALIFIED,
}

@Serializable
data class FirmwareEntry(
    val id: String? = null,
    val version: String? = null,
    val build: String? = null,
    @SerialName("os_name") val osName: String? = null,
    @SerialName("ios_major") val iosMajor: Int? = null,
    @SerialName("ipsw_filename") val ipswFilename: String? = null,
    @SerialName("download_url") val downloadUrl: String? = null,
    val sha256: String? = null,
    @SerialName("sha256_note") val sha256Note: String? = null,
    val signed: Boolean? = null,
    val status: FirmwareStatus,
    val stage: Stage = Stage.PLANNED,
)

@Serializable
data class Device(
    val identifier: String,
    val name: String,
    val board: String,
    val soc: String,
    @SerialName("soc_chip") val socChip: String,
    val arch: String,
    @SerialName("display_px") val displayPx: List<Int>,
    @SerialName("ram_mb") val ramMb: Int,
    val tier: DeviceTier,
    @SerialName("quick_start") val quickStart: Boolean = false,
    val firmwares: List<FirmwareEntry>,
)

@Serializable
data class Catalog(
    val schema: String,
    @SerialName("catalog_version") val catalogVersion: Int,
    @SerialName("generated_at_utc") val generatedAtUtc: String,
    @SerialName("generated_by") val generatedBy: String,
    val source: String,
    val verified: Boolean,
    @SerialName("quick_start") val quickStart: List<String>,
    val devices: List<Device>,
) {
    fun device(identifier: String): Device? = devices.firstOrNull { it.identifier == identifier }

    fun search(query: String): List<Device> {
        val q = query.trim().lowercase()
        if (q.isEmpty()) return devices
        return devices.filter {
            it.name.lowercase().contains(q) ||
                it.identifier.lowercase().contains(q) ||
                it.board.contains(q) ||
                it.soc.lowercase().contains(q) ||
                it.socChip.lowercase().contains(q)
        }
    }
}
